public class SymZ3DebuggerPcodeEmulatorTest : AbstractGhidraHeadedDebuggerTest {
	private DebuggerEmulationService emuService;

	/* @Before */
	public void setUpSymTest()
    {
		SymZ3TestUtils.skipTestIfUnsupportedPlatform();

		emuService = addPlugin(tool, typeof(DebuggerEmulationServicePlugin));
	}

	/* @Test */
	public void testFactoryDiscovered() {
		assertEquals(1, emuService.getEmulatorFactories()
				.stream()
				.filter(f => f is SymZ3EmulatorFactory)
				.count());
	}

	protected SchemaContext buildContext() {
		return new ToySchemaBuilder()
				.noRegisterGroups()
				.useRegistersPerFrame()
				.build();
	}

	/* @Test */
	public void testFactoryCreate()
    {
		emuService.setEmulatorFactory(new SymZ3EmulatorFactory());

		createAndOpenTrace();

		TraceThread thread;
		using (Transaction tid = tb.startTransaction())
{
			tb.createRootObject(buildContext(), "Target");
			thread = tb.getOrAddThread("Threads[0]", 0);
			tb.createObjectsFramesAndRegs(thread, Lifespan.nowOn(0), tb.host, 1);
		}

		traceManager.activateTrace(tb.trace);

		EmulationResult result =
			emuService.run(tb.host, TraceSchedule.snap(0), monitor, new _Anon_Scheduler_1());

		PcodeMachine<object> emu = emuService.getCachedEmulator(tb.trace, result.schedule());
		assertTrue(emu is SymZ3PcodeEmulator);

		SymZ3PcodeExecutorState state = (SymZ3PcodeExecutorState) emu.getSharedState();
		Msg.debug(this, "here is your state: " + state);
	}

	internal class _Anon_Scheduler_1 : Scheduler
	{

				int calls = 0;

				/* @Override */
				public TickStep nextSlice(Trace trace) {
					// Expect decode of uninitialized memory immediately
					assertEquals(0, calls++);
					return new TickStep(thread.getKey(), 1);
				}
			
	}

}
